&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Participate in threat modeling exercises with engineering team members for application and AI-driven architectures&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Triage SCA/SAST/DAST/CSPM findings by eliminating false positives and providing well-vetted vulnerabilities to engineering teams&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Support vulnerability management efforts for networks and infrastructure&lt;/span&gt;&lt;/li&gt;
